from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')
orig=s

IMG='data:image/jpeg;base64,'

thumb=f'<span class="srdm-app-icon srdm-thumb-icon" aria-label="SIPRI Portal screen 2"><img src="{IMG}" alt="SIPRI Portal screen" style="width:100%;height:100%;object-fit:cover;border-radius:12px;display:block"></span>'

pat=r'(<a class="srdm-app-card srdm-portal-card srdm-portal-planner-sipri"[^>]*>)(.*?)(</a>)'
m=re.search(pat,s,flags=re.S|re.I)
if not m:
    raise SystemExit('Planner-to-SIPRI dashboard card not found')
whole=m.group(0)
patched=re.sub(r'<span class="srdm-app-icon[^"]*"[^>]*>.*?</span>',thumb,whole,count=1,flags=re.S|re.I)
if patched==whole:
    raise SystemExit('Dashboard icon span not found')
s=s[:m.start()]+patched+s[m.end():]

if s!=orig:
    p.write_text(s,encoding='utf-8')
    print('Planner-to-SIPRI dashboard icon replaced with user screen 2 thumbnail.')
else:
    print('No change needed.')
